// Block (composition) — a centered outcome or status section.
// Stack owns arrangement. With `closesIn` the outcome closes itself after a time, as a kiosk's
// payment-complete screen returns to its start: a time limit, so it follows WCAG 2.2.1 (Timing
// Adjustable). The reader is told before time runs out and can ask for more with one press, at least
// 20 seconds ahead, and the count pauses while they are on it, as a toast's timer does.
import { useEffect, useId, useRef, useState, type ReactNode, type Ref } from "react";
import { Button } from "../components/Button";
import { Stack } from "../layouts/Stack";
import "./ResultState.css";

export interface ResultStateProps {
  /** Optional prominent result code, such as an HTTP status. */
  code?: string;
  /** Result heading. */
  title: string;
  /** Supporting explanation or next-step guidance. */
  description?: string;
  /** Consumer-supplied actions, typically Buttons or Links. */
  actions?: ReactNode;
  /**
   * Seconds until the outcome closes by itself; omit and it never does. Below 20 it is raised to 20,
   * the warning WCAG 2.2.1 gives a person to ask for more time.
   */
  closesIn?: number;
  /** Called when the time runs out. The consumer leaves the screen (a kiosk resets its session). */
  onClose?: () => void;
  /** The count, as one string with the seconds as data. */
  countdownLabel?: (seconds: number) => string;
  /** The action that restarts the time. */
  extendLabel?: string;
  /** Stops the count where it is (a receipt still printing). It also stops while pointer or focus is inside. */
  isPaused?: boolean;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function ResultState({
  code,
  title,
  description,
  actions,
  closesIn,
  onClose,
  countdownLabel = (seconds) => `Closes in ${seconds} ${seconds === 1 ? "second" : "seconds"}`,
  extendLabel = "More time",
  isPaused = false,
  className,
  ref,
}: ResultStateProps) {
  const titleId = useId();
  // Whole seconds, rounded up, so the count reaches zero; a value that is not a finite number never closes.
  const limit = closesIn == null || !Number.isFinite(closesIn) ? null : Math.max(Math.ceil(closesIn), WARNING_SECONDS);
  const [left, setLeft] = useState(limit);
  const [held, setHeld] = useState({ pointer: false, focus: false });
  // The warning is announced ONCE when the last 20 seconds begin: the visible count is a timer,
  // which a screen reader does not read out on every tick.
  const [warning, setWarning] = useState<string | null>(null);
  const close = useRef(onClose);
  const label = useRef(countdownLabel);
  useEffect(() => {
    close.current = onClose;
    label.current = countdownLabel;
  });
  useEffect(() => {
    setLeft(limit);
    setWarning(null);
  }, [limit]);
  const running = left != null && left > 0 && !isPaused && !held.pointer && !held.focus;
  useEffect(() => {
    if (!running) return;
    const id = setTimeout(() => setLeft((s) => (s == null ? s : s - 1)), 1000);
    return () => clearTimeout(id);
  }, [running, left]);
  // Keyed on `left` alone, so the close fires once when the count reaches zero, however often the
  // consumer re-renders afterwards.
  useEffect(() => {
    if (left === 0) close.current?.();
  }, [left]);
  useEffect(() => {
    if (left != null && left > 0 && left <= WARNING_SECONDS && warning == null) setWarning(label.current(left));
  }, [left, warning]);

  return (
    <Stack
      as="section"
      ref={ref}
      aria-labelledby={titleId}
      onPointerEnter={limit == null ? undefined : () => setHeld((h) => ({ ...h, pointer: true }))}
      onPointerLeave={limit == null ? undefined : () => setHeld((h) => ({ ...h, pointer: false }))}
      onFocus={limit == null ? undefined : () => setHeld((h) => ({ ...h, focus: true }))}
      onBlur={limit == null ? undefined : (event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setHeld((h) => ({ ...h, focus: false }));
      }}
      align="center"
      gap="large"
      className={className ? `sd-resultstate ${className}` : "sd-resultstate"}
    >
      <Stack align="center" gap="small" className="sd-resultstate__outcome">
        {code && <span className="sd-resultstate__code sd-type-display-medium">{code}</span>}
        {/* Grouped for the same reason as `EmptyState` and `PageHeader`: the outcome's name and the
            line explaining it are ONE unit, so they sit at a tighter rung than the section's own. */}
        <Stack gap="x-small" align="center" className="sd-resultstate__heading">
          <h2 id={titleId} className="sd-resultstate__title sd-type-title-medium">
            {title}
          </h2>
          {description && (
            <p className="sd-resultstate__description sd-type-body-medium">{description}</p>
          )}
        </Stack>
        {actions}
      </Stack>
      {/* The count is about the whole outcome, not its actions, so it is parted from them. */}
      {left != null && (
        <Stack direction="row" align="center" justify="center" gap="small" wrap className="sd-resultstate__countdown">
          <p role="timer" className="sd-resultstate__count sd-type-caption-medium">
            {countdownLabel(left)}
          </p>
          <Button
            variant="secondary"
            onPress={() => {
              setLeft(limit);
              setWarning(null);
            }}
          >
            {extendLabel}
          </Button>
          <span className="sd-visually-hidden" aria-live="polite">
            {warning}
          </span>
        </Stack>
      )}
    </Stack>
  );
}

/** How long before the end a reader is warned, and the least time a closing outcome may run. */
const WARNING_SECONDS = 20;

/* ResultState.css — .sd-resultstate (Block)
   Arrangement only: a result section centred in the column it is given; Stack owns flow. */
.sd-resultstate {
  width: 100%;
  text-align: center;
}

.sd-resultstate__code,
.sd-resultstate__title,
.sd-resultstate__description,
.sd-resultstate__count {
  margin: 0;
}

.sd-resultstate__description {
  color: var(--sd-color-text-muted);
}
